// @vitest-environment node
import { describe, expect, it } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';

import { ProfileSettingsPage } from './ProfileSettingsPage';
import type { ProfileValues } from './model';

const INITIAL: ProfileValues = {
  name: 'Анна Смирнова',
  email: 'anna@example.com',
  avatarUrl: null,
  language: 'ru',
  timezone: 'Europe/Moscow',
  twoFactorEnabled: false,
  notifications: { productNews: true, systemAlerts: true, weeklyDigest: false },
};

describe('ProfileSettingsPage SSR smoke', () => {
  it('renders all fields, notification checkboxes and action buttons', () => {
    const html = renderToStaticMarkup(
      <ThemeProvider theme="light">
        <ProfileSettingsPage initialValues={INITIAL} onSave={async (v) => v} />
      </ThemeProvider>,
    );
    for (const text of [
      'Настройки профиля',
      'Аватар',
      'Загрузить аватар',
      'Имя',
      'Email',
      'Язык интерфейса',
      'Часовой пояс',
      'Двухфакторная авторизация',
      'Выключена',
      'Email-уведомления',
      'Новости продукта',
      'Системные алерты',
      'Дайджест за неделю',
      'Сохранить',
      'Отмена',
    ]) {
      expect(html, `missing: ${text}`).toContain(text);
    }
    expect(html).toContain('Anna Smirnova'.length ? 'Анна Смирнова' : '');
    // Изменений ещё нет — кнопка «Сохранить» должна быть disabled.
    const saveButton = html.match(/<button[^>]*type="submit"[^>]*>/)?.[0] ?? '';
    expect(saveButton).toMatch(/disabled/);
  });
});

